package com.mzuriair.app.presentation;
import androidx.lifecycle.*; import com.mzuriair.app.data.model.Telemetry; import com.mzuriair.app.data.repository.TelemetryRepository; import com.mzuriair.app.connectivity.WatchDataSource; import java.util.*;
public class MainViewModel extends ViewModel { public final MutableLiveData<Telemetry> telemetry=new MutableLiveData<>(); public final MutableLiveData<String> error=new MutableLiveData<>(); public final MutableLiveData<Boolean> loading=new MutableLiveData<>(false); private final TelemetryRepository repo; public MainViewModel(TelemetryRepository r){repo=r;} public void refresh(){loading.setValue(true);repo.latest(new WatchDataSource.Callback(){public void onTelemetry(Telemetry t){loading.postValue(false);telemetry.postValue(t);}public void onError(String m){loading.postValue(false);error.postValue(m);}});} public void sos(){repo.sos(new WatchDataSource.Callback(){public void onTelemetry(Telemetry t){}public void onError(String m){error.postValue(m);}});} }
